-- Smash history: majors from 2017 on that aren't on start.gg (round 540 couldn't find them there), added
-- by hand from Liquipedia (Matthew, 2026-11-19: "read liquipedia by hand if it's the best source"): each
-- tournament's own page read in Matthew's Chrome, several seconds apart, for its date, city, entrant count and
-- top 8. Facts only, credited to that page (CC-BY-SA). Added as majors "added by hand" (source 'manual'), like
-- the 2003-2016 ones. Safe to run twice (existing slugs are skipped).

insert into public.majors (slug, name, start_at, end_at, games, entrants, city, country, source_url, source, results_saved_at, live_notified_at)
select v.slug, v.name, v.start_at::timestamptz, v.end_at::timestamptz, v.games, v.entrants, v.city, v.country, v.source_url, 'manual', now(), now()
from (values
  ('manual/2017-smash-rivalries', 'Smash Rivalries', '2017-04-08T12:00:00Z', '2017-04-10T00:00:00Z', array['melee']::text[], 16, 'Burbank', 'US', 'https://liquipedia.net/smash/Smash_Rivalries'),
  ('manual/2017-canada-cup-2017', 'Canada Cup 2017', '2017-10-27T12:00:00Z', '2017-10-30T00:00:00Z', array['melee']::text[], 170, 'Toronto', 'CA', 'https://liquipedia.net/smash/Canada_Cup/2017/Melee'),
  ('manual/2018-umebura-wii-u-final', 'Umebura Wii U Final', '2018-12-01T12:00:00Z', '2018-12-03T00:00:00Z', array['smash4']::text[], 515, 'Tokyo', 'JP', 'https://liquipedia.net/smash/Umebura/Wii_U_Final'),
  ('manual/2019-mango-s-birthday-bash', 'Mango''s Birthday Bash', '2019-12-07T12:00:00Z', '2019-12-09T00:00:00Z', array['melee']::text[], 226, 'Toronto', 'CA', 'https://liquipedia.net/smash/Mango%27s_Birthday_Bash/Melee'),
  ('manual/2023-the-back-hit', 'The Back Hit', '2023-03-18T12:00:00Z', '2023-03-19T00:00:00Z', array['pplus']::text[], 97, 'Plano', 'US', 'https://liquipedia.net/smash/The_Back_Hit'),
  ('manual/2024-pat-s-house-4', 'Pat''s House 4', '2024-04-27T12:00:00Z', '2024-04-29T00:00:00Z', array['melee']::text[], 307, 'La Jolla', 'US', 'https://liquipedia.net/smash/Pat%27s_House/4'),
  ('manual/2024-tipped-off-15', 'Tipped Off 15', '2024-06-15T12:00:00Z', '2024-06-17T00:00:00Z', array['melee']::text[], 513, 'Marietta', 'US', 'https://liquipedia.net/smash/Tipped_Off/15'),
  ('manual/2025-nounsvitational-tokyo-2025', 'Nounsvitational Tokyo 2025', '2025-12-05T12:00:00Z', '2025-12-08T00:00:00Z', array['melee']::text[], 16, 'Tokyo', 'JP', 'https://liquipedia.net/smash/Nounsvitational/2025'),
  ('manual/2026-hitstun-7', 'Hitstun 7', '2026-01-09T12:00:00Z', '2026-01-12T00:00:00Z', array['smash64']::text[], 68, 'Dallas', 'US', 'https://liquipedia.net/smash/Hitstun/7'),
  ('manual/2026-tipped-off-17-haunted', 'Tipped Off 17: Haunted', '2026-10-31T12:00:00Z', '2026-11-02T00:00:00Z', array['melee']::text[], 260, 'Atlanta', 'US', 'https://liquipedia.net/smash/Tipped_Off/17')
) as v (slug, name, start_at, end_at, games, entrants, city, country, source_url)
on conflict (slug) do nothing;

